record.field:
picking = env['stock.picking'].browse(record.res_id).exists()

picking.action_assign()

tracked_moves = picking.move_ids.filtered(
    lambda move:
        move.state not in ('done', 'cancel')
        and move.product_id.tracking in ('lot', 'serial')
)

incomplete_moves = tracked_moves.filtered(
    lambda move:
        move.product_uom.compare(
            move.quantity,
            move.product_uom_qty,
        ) < 0
)

missing_lot_lines = tracked_moves.mapped(
    'move_line_ids'
).filtered(
    lambda line:
        line.quantity > 0 and not line.lot_id
)

if incomplete_moves or missing_lot_lines:
    record.write({
        'active': True,
        'feedback': False,
    })
else:
    validate_activity_type = env.ref(
        'fmcg_business_automation.'
        'mail_activity_type_validate_assigned_picking'
    )

    picking.activity_schedule(
        activity_type_id=validate_activity_type.id,
        summary='Validate assigned stock picking',
        user_id=record.user_id.id or env.user.id,
    )
